import type { Db } from "./db";

/**
 * Idempotent schema. Every statement is safe to re-run; new columns are added with
 * ADD COLUMN IF NOT EXISTS below the CREATE TABLE they belong to.
 * IDs are random text generated by the app (portable across Postgres and PGlite).
 */
const STATEMENTS = [
  `CREATE TABLE IF NOT EXISTS schools (
    id text PRIMARY KEY,
    slug text NOT NULL UNIQUE,
    name jsonb NOT NULL,
    branding jsonb NOT NULL,
    contact jsonb NOT NULL,
    landing jsonb NOT NULL,
    plan text NOT NULL DEFAULT 'starter',
    status text NOT NULL DEFAULT 'trial',
    student_limit integer,
    retention_days integer,
    custom_domain text UNIQUE,
    paid_until text,
    billing_note text,
    feature_overrides jsonb NOT NULL DEFAULT '{}'::jsonb,
    collect_phone boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL
  )`,
  `CREATE TABLE IF NOT EXISTS branches (
    id text PRIMARY KEY,
    school_id text NOT NULL REFERENCES schools(id) ON DELETE CASCADE,
    name text NOT NULL,
    address text,
    map_url text,
    phone text,
    created_at timestamptz NOT NULL
  )`,
  `CREATE INDEX IF NOT EXISTS branches_school_idx ON branches(school_id)`,
  `CREATE TABLE IF NOT EXISTS users (
    id text PRIMARY KEY,
    email text NOT NULL UNIQUE,
    name text NOT NULL,
    role text NOT NULL,
    school_id text REFERENCES schools(id) ON DELETE CASCADE,
    branch_id text REFERENCES branches(id) ON DELETE SET NULL,
    last_login_at timestamptz,
    created_at timestamptz NOT NULL
  )`,
  `CREATE INDEX IF NOT EXISTS users_school_idx ON users(school_id)`,
  `CREATE TABLE IF NOT EXISTS login_tokens (
    id text PRIMARY KEY,
    user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash text NOT NULL UNIQUE,
    expires_at timestamptz NOT NULL,
    used_at timestamptz,
    created_at timestamptz NOT NULL
  )`,
  `CREATE TABLE IF NOT EXISTS sessions (
    id text PRIMARY KEY,
    user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash text NOT NULL UNIQUE,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL
  )`,
  `CREATE TABLE IF NOT EXISTS invite_codes (
    code text PRIMARY KEY,
    school_id text NOT NULL REFERENCES schools(id) ON DELETE CASCADE,
    label text,
    branch_id text REFERENCES branches(id) ON DELETE SET NULL,
    instructor_id text REFERENCES users(id) ON DELETE SET NULL,
    max_uses integer,
    uses integer NOT NULL DEFAULT 0,
    expires_at timestamptz,
    active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL
  )`,
  `CREATE INDEX IF NOT EXISTS invite_codes_school_idx ON invite_codes(school_id)`,
  `CREATE TABLE IF NOT EXISTS students (
    id text PRIMARY KEY,
    school_id text NOT NULL REFERENCES schools(id) ON DELETE CASCADE,
    display_name text NOT NULL,
    phone text,
    status text NOT NULL,
    package text,
    branch_id text REFERENCES branches(id) ON DELETE SET NULL,
    instructor_id text REFERENCES users(id) ON DELETE SET NULL,
    payment_note text,
    exam_date text,
    lesson_date text,
    notes text,
    source text,
    interest text,
    consent_at timestamptz,
    consent_version text,
    login_code_hash text UNIQUE,
    linked_at timestamptz,
    progress jsonb,
    metrics jsonb,
    progress_saved_at timestamptz,
    last_active_at timestamptz,
    created_at timestamptz NOT NULL
  )`,
  `CREATE INDEX IF NOT EXISTS students_school_idx ON students(school_id, status)`,
  `CREATE TABLE IF NOT EXISTS device_tokens (
    id text PRIMARY KEY,
    student_id text NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    token_hash text NOT NULL UNIQUE,
    last_used_at timestamptz,
    created_at timestamptz NOT NULL
  )`,
  `CREATE TABLE IF NOT EXISTS appointments (
    id text PRIMARY KEY,
    school_id text NOT NULL REFERENCES schools(id) ON DELETE CASCADE,
    student_id text REFERENCES students(id) ON DELETE CASCADE,
    name text NOT NULL,
    phone text,
    kind text NOT NULL,
    preferred_at text NOT NULL,
    status text NOT NULL DEFAULT 'requested',
    branch_id text REFERENCES branches(id) ON DELETE SET NULL,
    message text,
    notes text,
    consent_at timestamptz,
    created_at timestamptz NOT NULL
  )`,
  `CREATE INDEX IF NOT EXISTS appointments_school_idx ON appointments(school_id, status)`,
  `CREATE TABLE IF NOT EXISTS question_notes (
    id text PRIMARY KEY,
    school_id text NOT NULL REFERENCES schools(id) ON DELETE CASCADE,
    author_id text REFERENCES users(id) ON DELETE SET NULL,
    author_name text NOT NULL,
    question_id integer NOT NULL,
    visibility text NOT NULL,
    body text NOT NULL,
    video_url text,
    created_at timestamptz NOT NULL
  )`,
  `CREATE INDEX IF NOT EXISTS question_notes_school_idx ON question_notes(school_id, question_id)`,
  `CREATE TABLE IF NOT EXISTS question_flags (
    id text PRIMARY KEY,
    school_id text NOT NULL REFERENCES schools(id) ON DELETE CASCADE,
    user_id text REFERENCES users(id) ON DELETE SET NULL,
    question_id integer NOT NULL,
    reason text,
    created_at timestamptz NOT NULL
  )`,
  `CREATE INDEX IF NOT EXISTS question_flags_school_idx ON question_flags(school_id)`,
  `CREATE TABLE IF NOT EXISTS classroom_sessions (
    id text PRIMARY KEY,
    code text NOT NULL,
    school_id text NOT NULL REFERENCES schools(id) ON DELETE CASCADE,
    host_user_id text REFERENCES users(id) ON DELETE SET NULL,
    question_ids jsonb NOT NULL,
    anonymous boolean NOT NULL DEFAULT false,
    phase text NOT NULL DEFAULT 'lobby',
    idx integer NOT NULL DEFAULT -1,
    revealed_index integer NOT NULL DEFAULT -1,
    created_at timestamptz NOT NULL,
    ended_at timestamptz
  )`,
  `CREATE INDEX IF NOT EXISTS classroom_sessions_code_idx ON classroom_sessions(code, phase)`,
  `CREATE TABLE IF NOT EXISTS classroom_participants (
    id text PRIMARY KEY,
    session_id text NOT NULL REFERENCES classroom_sessions(id) ON DELETE CASCADE,
    name text NOT NULL,
    seq integer NOT NULL DEFAULT 0,
    token_hash text NOT NULL UNIQUE,
    created_at timestamptz NOT NULL
  )`,
  `ALTER TABLE classroom_participants ADD COLUMN IF NOT EXISTS seq integer NOT NULL DEFAULT 0`,
  `CREATE INDEX IF NOT EXISTS classroom_participants_session_idx ON classroom_participants(session_id)`,
  `CREATE TABLE IF NOT EXISTS classroom_answers (
    session_id text NOT NULL REFERENCES classroom_sessions(id) ON DELETE CASCADE,
    participant_id text NOT NULL REFERENCES classroom_participants(id) ON DELETE CASCADE,
    question_index integer NOT NULL,
    selected integer NOT NULL,
    correct boolean NOT NULL,
    created_at timestamptz NOT NULL,
    PRIMARY KEY (participant_id, question_index)
  )`,
  `CREATE INDEX IF NOT EXISTS classroom_answers_session_idx ON classroom_answers(session_id, question_index)`,
  `CREATE TABLE IF NOT EXISTS events (
    day text NOT NULL,
    school_id text NOT NULL,
    kind text NOT NULL,
    ref text NOT NULL DEFAULT '',
    count integer NOT NULL DEFAULT 0,
    PRIMARY KEY (day, school_id, kind, ref)
  )`,
  `CREATE INDEX IF NOT EXISTS events_school_idx ON events(school_id, day)`,
  `CREATE TABLE IF NOT EXISTS audit_log (
    id text PRIMARY KEY,
    at timestamptz NOT NULL,
    actor_email text,
    school_id text,
    action text NOT NULL,
    target text,
    meta jsonb
  )`,
  `CREATE INDEX IF NOT EXISTS audit_log_school_idx ON audit_log(school_id, at)`,
  `CREATE TABLE IF NOT EXISTS error_reports (
    id text PRIMARY KEY,
    at timestamptz NOT NULL,
    first_at timestamptz NOT NULL,
    message text NOT NULL,
    stack text,
    path_key text NOT NULL DEFAULT '',
    path text,
    release text,
    count integer NOT NULL DEFAULT 1,
    UNIQUE (message, path_key)
  )`
];

const migrated = new WeakMap<Db, Promise<void>>();

/** Runs the migrations once per Db instance (per process). */
export function migrate(db: Db): Promise<void> {
  let pending = migrated.get(db);
  if (!pending) {
    // One multi-statement batch on a single connection, serialised with an advisory lock so
    // concurrent cold starts (serverless) don't race on CREATE TABLE IF NOT EXISTS.
    const batch = [
      "BEGIN",
      "SELECT pg_advisory_xact_lock(727274)",
      ...STATEMENTS,
      "COMMIT"
    ].join(";\n");
    pending = db.exec(batch);
    pending.catch(() => migrated.delete(db));
    migrated.set(db, pending);
  }
  return pending;
}
